import assert from "node:assert/strict";
import { test } from "node:test";
import { formatName } from "../src/format.ts";

test("grader: formatName", () => {
  assert.equal(formatName(null), "");
  assert.equal(formatName(undefined), "");
  assert.equal(formatName({ first: "Ada" }), "Ada");
  assert.equal(formatName({ first: "Ada", last: "Lovelace" }), "Ada Lovelace");
  assert.equal(formatName({ first: "", last: "X" }), "X");
});

