export interface User {
  first: string;
  last?: string;
}

export function formatName(user: User | null | undefined): string {
  if (!user) return "";
  return [user.first, user.last]
    .filter((part): part is string => typeof part === "string" && part.length > 0)
    .join(" ");
}

